    // Geometries cannot be shared between elements, so parse a fresh instance per use.
    public static Geometry Geometry(string data) => (Geometry)XamlBindingHelper.ConvertValue(typeof(Geometry), data);

    public static PathIcon Icon(string data) => new() { Data = Geometry(data) };

    public static string ForQuery(string expression)
    {
        var text = expression.ToLowerInvariant();
        if (text.Contains("review-requested:") || text.Contains("reviewed-by:") || text.Contains("/pulls/reviews")) return Eye;
        if (text.Contains("is:pr") || text.Contains("type:pr") || text.Contains("/pulls")) return PullRequest;
        if (text.Contains("is:issue") || text.Contains("type:issue") || text.Contains("/issues")) return IssueOpened;
        if (text.Contains("mentions:") || text.Contains("involves:") || text.Contains("commenter:")) return Mention;
        if (text.Contains("author:") || text.Contains("assignee:")) return Person;
        return Inbox;
    }
